	if not check("playback_valid", playback != null, "L'AnimationTree deve contenere il parametro parameters/playback"):
		return

	player.global_position = Vector3(0.0, 3.0, -4.0)
	player.velocity = Vector3.ZERO
	for i in range(30):
		await wait_physics_frames(1)
		if player.is_on_floor():
			break

	if not check("on_floor", player.is_on_floor(), "Il personaggio deve trovarsi sul pavimento all'inizio"):
		return

	await wait_physics_frames(5)
	var initial_state: String = playback.get_current_node()
	if not check("state_ground", initial_state == "Ground", "A terra lo stato della macchina a stati deve essere Ground (attuale: %s)" % initial_state):
		return

	var walk_speed: float = float(get_prop(player, "walk_speed", 5.0))
	Input.action_press("move_forward")
	await wait_physics_frames(20)
	var walk_pos = anim_tree.get("parameters/Ground/blend_position")
	check("blend_walk", walk_pos != null and absf(float(walk_pos) - walk_speed) < 0.6, "Camminando a terra blend_position deve valere circa %.1f (misurato: %s)" % [walk_speed, str(walk_pos)])
	Input.action_release("move_forward")

	await wait_physics_frames(10)
	await tap_action("jump")
	await wait_physics_frames(4)
	var jump_state: String = playback.get_current_node()
	check("state_jump", jump_state == "Jump", "Durante la salita del salto lo stato deve essere Jump (attuale: %s)" % jump_state)

	var fell := false
	for i in range(50):
		await wait_physics_frames(1)
		if player.velocity.y < -0.5 and not player.is_on_floor():
			fell = true
			break

	if check("reached_fall", fell, "Il personaggio deve iniziare a scendere dopo il salto"):
		var fall_state: String = playback.get_current_node()
		check("state_fall", fall_state == "Fall", "Durante la caduta lo stato deve essere Fall (attuale: %s)" % fall_state)

	var landed := false
	for i in range(60):
		await wait_physics_frames(1)
		if player.is_on_floor():
			landed = true
			break

	if check("landed", landed, "Il personaggio deve atterrare sul terreno"):
		await wait_physics_frames(3)
		var landed_state: String = playback.get_current_node()
		check("state_landed", landed_state == "Ground", "All'atterraggio lo stato deve ritornare a Ground (attuale: %s)" % landed_state)

